import javax.swing.*;
import java.awt.*;
import java.sql.*;
import java.util.*;

public class DatabaseAtt extends JPanel {
    private final boolean editable; private JTable table;
    public DatabaseAtt(boolean editable){this.editable=editable;setLayout(new BorderLayout(8,8));setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton refresh=new JButton("Refresh");refresh.addActionListener(e->load());actions.add(refresh);if(editable){JButton update=new JButton("Record attendance");update.addActionListener(e->update());actions.add(update);}add(actions,BorderLayout.NORTH);table=new JTable();add(new JScrollPane(table),BorderLayout.CENTER);load();}
    private void load(){try{java.util.List<String[]> rows=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT a.id,s.code,s.name,a.classes_attended,a.classes_held FROM attendance a JOIN subjects s ON s.id=a.subject_id ORDER BY s.code")){while(r.next()){int at=r.getInt(4),held=r.getInt(5);rows.add(new String[]{r.getString(1),r.getString(2),r.getString(3),String.valueOf(at),String.valueOf(held),String.format(Locale.US,"%.1f%%",AttendanceCalc.percentage(at,held)),AttendanceCalc.status(at,held),String.valueOf(AttendanceCalc.classesNeeded(at,held,75))});}}JScrollPane old=(JScrollPane)getComponent(1);table=TableRender.table(new String[]{"ID","Code","Subject","Attended","Held","Percentage","Status","Classes needed for 75%"},rows);remove(old);add(new JScrollPane(table),BorderLayout.CENTER);revalidate();repaint();}catch(Exception e){error(e);}}
    private void update(){String id=TableRender.selectedId(table);if(id==null){JOptionPane.showMessageDialog(this,"Select a subject first.");return;}int row=table.convertRowIndexToModel(table.getSelectedRow());int oldAtt=Integer.parseInt(String.valueOf(table.getModel().getValueAt(row,3))),oldHeld=Integer.parseInt(String.valueOf(table.getModel().getValueAt(row,4)));JTextField held=new JTextField(String.valueOf(oldHeld)),att=new JTextField(String.valueOf(oldAtt));Object[] f={"Classes held",held,"Classes attended",att};if(JOptionPane.showConfirmDialog(this,f,"Record attendance",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{int h=Integer.parseInt(held.getText()),a=Integer.parseInt(att.getText());if(h<0||a<0||a>h)throw new IllegalArgumentException("Use non-negative numbers; attended cannot exceed held.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE attendance SET classes_held=?,classes_attended=? WHERE id=?")){p.setInt(1,h);p.setInt(2,a);p.setInt(3,Integer.parseInt(id));p.executeUpdate();}load();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Attendance",JOptionPane.ERROR_MESSAGE);}
}
